"""Compute bounded fine-tuning estimates from Colab timing evidence."""
import json,statistics
from pathlib import Path
p=Path(__file__).resolve().parent
b=json.loads((p/'colab02/bench_results/bench.done').read_text())
a=b['AIR']['median_seconds'];s=b['Surface']['median_seconds']
N1=365*24;N3=3*N1;frames=48;logical=frames*39*440*408*4
min_h=N1*s/3600;full_h=N3*5*(a+s)/3600
# An *assumed* 1.5--3x total-runtime multiplier covers frozen global preprocessing,
# data loading and other overhead, not measured in the synthetic timing.
min_range=(min_h*1.5,min_h*3);full_range=(full_h*1.5,full_h*3)
# Local April sample archives observed from HF ZIP; yearly extrapolation is an assumption.
era_daily=833685705;hrrr_day_lo=150_000_000;hrrr_day_hi=185_000_000
store=lambda years:tuple(years*365*(era_daily+x)/1e9 for x in (hrrr_day_lo,hrrr_day_hi))
lo1,hi1=store(1);lo3,hi3=store(3)
rows=['# L26.4 Colab A100 微调代价估算（版本 02）','','本报告只做成本估算，不等于德州已微调或有迁移收益。数据来源：Zhang et al. (2026) 主文 PDF p.15（文献卡 `16_PETW/05_Literature_Wiki/wiki/ai_weather/papers/XK2I5KR3_zhang_2026_aero_ode.md`，第 19–21 行）、作者公开 2024-04 HF 样本、Colab A100 实测 `colab02/bench_results/`。原 `finetune_cost.md` 是 10-19 未计时的历史记录，本版不覆盖。','','定义：N = 训练有效起报数；E = epoch 数；tAIR、tSurface 是一份 48 h 样本对应区域网络的前向＋反向＋AdamW 更新秒数。给定 N 的区域网计算基准：最小 GPU·h = N×E×tSurface/3600；作者双网 GPU·h = N×E×(tAIR+tSurface)/3600。表中 N 取日历上界，所以数值是“假定全日历有效”的条件估算；若缺测，实际 N 会降低，而未测流水线开销又会升高总用量，不能把表中数值称为总训练时间的严格下界。**这是单卡 A100 合计 GPU 时间，不是 4×H800 墙钟。** 冻结 NeuralGCM、数据加载、跨设备通信、验证/保存未计。','','实测条件：`colab02/bench_finetune_colab.py`，真实审核过 SHA-256 的官方 AIR/Surface 权重 `torch.load(weights_only=True)`；440×408，70/74 动态通道＋5/14 静态通道；用与训练形状相同的随机张量对 48 个逐小时帧分别前向、反向，并在 48 帧后做一次 AdamW step。GPU NVIDIA A100-SXM4-80GB；每网独立进程各重复三次，冻结 NeuralGCM 未运行，CPU/I/O 未计。随机数据只用于耗时，不用于任何科学评分；和作者 batch=2、混合精度及多卡并行不同，吞吐不可直接等同。','','| 因子 | 最小可行微调 | 作者同规格 | 来源/性质 |','|---|---:|---:|---|',f'| 日历样本上界 N | {N1:,}（假设德州 1 年逐小时全有效） | {N3:,}（2021–2023 全小时） | 论文 PDF p.15 逐小时、48 h；有效样本数未给，缺测则减少 |','| E / 网络 | Surface 1 epoch（假设） | AIR 与 Surface 各 5 epochs | 论文 PDF p.15，最小档是假设 |','| batch | 1–2（假设） | 2 | 论文 PDF p.15；实测循环每帧 batch 1，需用 batch 2 重测吞吐 |',f'| 单样本逻辑 HRRR 原始监督张量 | {logical:,} B（{logical/2**30:.3f} GiB） | 同 | 48×39×440×408×float32；39/网格来自 HF 日 HDF5 `/data` shape (24,39,440,408)，float32 假设；窗口重叠，不乘 N 作物理存储 |',f'| tAIR（s） | 不训练 | {a:.3f}，三次 {b["AIR"]["seconds"]} | Colab `bench.done` 和每次 trial JSON |',f'| tSurface（s） | {s:.3f} | {s:.3f}，三次 {b["Surface"]["seconds"]} | 同上 |',f'| 区域网计算基准（假定全日历有效） | {min_h:,.1f} GPU·h | {full_h:,.1f} GPU·h | 上式、日历全有效、A100 单卡串行等效 |',f'| 含未测开销的探索区间 | {min_range[0]:,.1f}–{min_range[1]:,.1f} GPU·h | {full_range[0]:,.1f}–{full_range[1]:,.1f} GPU·h | 假设总倍率 1.5–3×，**非实测**，用于容量预留，不当作预测精度/训练实绩 |',f'| 独立原始数据存储粗估 | {lo1:,.0f}–{hi1:,.0f} GB | {lo3:,.0f}–{hi3:,.0f} GB | 假设 2024-04 HF 每日 ERA5 {era_daily:,} B 与 HRRR 150–185 MB 按 365/1095 天线性外推；实际年度压缩率/缺测未知 |','| SU | 在 Colab 执行：0 CRC/TACC SU；换 CRC 则未知 | 同 | CRC GPU→SU 计费换算未提供，不虚构数值 |','','限制：最低档“只调 Surface／1 年／1 epoch”是成本情景，不代表足够收敛；作者同规格日历小时是上界，训练中还可能需 48 h 尾部完整窗口；冻结 NeuralGCM 每个样本是否可复用和开销未核。实测只测试区域网络训练步，因此 GPU·h 的条件基准和带假设区间均不等于完整端到端训练总耗时。要把区间收窄，需要真实德州样本的 GCM 生成、数据管线、batch=2 与多卡短测。','','出处：论文 https://doi.org/10.1038/s41612-026-01555-w （PDF p.15），代码 https://github.com/ZZzzzZZZV/AERO_ODE （Apache-2.0），公开样本 https://huggingface.co/datasets/ZhangJing1106170090/AERO_ODE_Case_Data （CC-BY-NC-4.0）；NeuralGCM https://github.com/google-research/neuralgcm 。']
out=p/'finetune_cost_colab02.md';out.write_text('\n'.join(rows)+'\n');print(out,'min_gpu_h',min_h,'author_gpu_h',full_h,'storage_GB',store(1),store(3))
